// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
// 1. Schema Definition


export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 4, // Ignored in internal math to keep the specific 4s pacing requested, but standard for schema
  accentColor = "#00A3A3",
  columns = 12,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Layout Math ---
  const iconSize = width / columns;
  const rawRows = Math.ceil(height / iconSize);
  // Ensure an odd number of rows so there is always a perfect center row, plus extra padding for bleed
  const numRows = rawRows % 2 === 0 ? rawRows + 3 : rawRows + 2;
  const centerIndex = Math.floor(numRows / 2);
  const maxD = Math.floor(numRows / 2);

  const gridHeight = numRows * iconSize;
  const startY = (height - gridHeight) / 2;
  const centerY = startY + centerIndex * iconSize;

  // --- Animation Timings ---
  // Phase 1: Center row builds (frames 0 to 30)
  const centerBuildDuration = 30;
  const colStagger = centerBuildDuration / columns;

  // Phase 2: Spread outwards (frames 45 to 105)
  const spreadStartFrame = 45;
  const spreadDuration = 60;
  const stepDuration = 20;

  // Calculate stagger per row to ensure the outermost row finishes spreading by frame 105
  // Total time available for cascading starts is spreadDuration - stepDuration
  const rowStagger =
    maxD > 1 ? (spreadDuration - stepDuration) / (maxD - 1) : 0;

  // --- Calculate Offsets for Cascade Effect ---
  // Each row distance 'd' defines how far it pushes itself (and all rows beyond it) outward.
  const offsets = new Array(maxD + 1).fill(0);
  for (let d = 1; d <= maxD; d++) {
    const stepStart = spreadStartFrame + (d - 1) * rowStagger;
    offsets[d] = interpolate(
      frame,
      [stepStart, stepStart + stepDuration],
      [0, iconSize],
      {
        easing: Easing.inOut(Easing.cubic),
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    );
  }

  // --- Render Helpers ---
  const renderIcon = (rowIndex: number, colIndex: number, d: number) => {
    // 1. Scale Animation: All rows inherit the scale-in timing of the center row
    const scale = spring({
      frame: frame - colIndex * colStagger,
      fps,
      config: { damping: 14, stiffness: 150, mass: 0.8 },
    });

    // 2. Y Position Logic: Cascade accordion
    const sign = Math.sign(rowIndex - centerIndex); // -1 for above, 1 for below, 0 for center
    let totalOffset = 0;
    for (let k = 1; k <= d; k++) {
      totalOffset += offsets[k];
    }
    const currentY = centerY + sign * totalOffset;
    const currentX = colIndex * iconSize;

    return (
      <div
        key={`icon-${rowIndex}-${colIndex}`}
        style={{
          position: "absolute",
          left: currentX,
          top: currentY,
          width: iconSize,
          height: iconSize,
          transform: `scale(${scale})`,
          // Small optimization: hide if fully scaled down to prevent rendering invisible nodes
          opacity: scale > 0.01 ? 1 : 0,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        <svg
          viewBox="0 0 100 100"
          width="100%"
          height="100%"
          style={{ transition: "none" }}
        >
          {/* 
            The mask creates the transparent "cutouts" in the teal circle. 
            By masking out the head and shoulders, the background behind the SVG naturally shows through.
          */}
          <circle
            cx="50"
            cy="50"
            r="46"
            fill={accentColor}
            mask="url(#avatar-silhouette-mask)"
            style={{ transition: "none" }}
          />
        </svg>
      </div>
    );
  };

  const renderRow = (rowIndex: number, d: number) => {
    const cols = [];
    for (let c = 0; c < columns; c++) {
      cols.push(renderIcon(rowIndex, c, d));
    }
    return cols;
  };

  // --- Render Order Logic ---
  // To ensure rows "slide out from behind" the center row, outer rows must be rendered FIRST (lower z-index).
  // The center row (d=0) is rendered LAST so it sits perfectly on top of everything.
  const rowsToRender = [];
  for (let d = maxD; d >= 0; d--) {
    if (d === 0) {
      rowsToRender.push(renderRow(centerIndex, 0));
    } else {
      // Render above and below symmetrically
      rowsToRender.push(renderRow(centerIndex - d, d));
      rowsToRender.push(renderRow(centerIndex + d, d));
    }
  }

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Global SVG Definitions */}
      <svg width="0" height="0" style={{ position: "absolute" }}>
        <defs>
          <mask id="avatar-silhouette-mask">
            {/* White area keeps the teal circle visible */}
            <circle cx="50" cy="50" r="100" fill="white" />
            {/* Black areas hide the teal, creating the silhouette holes */}
            <circle cx="50" cy="38" r="16" fill="black" />
            {/* Shoulders path: starts wide at bottom, curves up to shoulders, and back down */}
            <path
              d="M 10 110 C 10 65, 28 58, 50 58 C 72 58, 90 65, 90 110 Z"
              fill="black"
            />
          </mask>
        </defs>
      </svg>

      {/* Rendered Grid */}
      {rowsToRender}
    </AbsoluteFill>
  );
};

export default ComponentName;